examples.code_or_diagram:
-- BIG BANG (Downtime 1-2h, tabela grande)
ALTER TABLE users ADD COLUMN age INT;
-- Reescreve todas 50M linhas, tabela locked

-- ZERO-DOWNTIME (Seguro)
-- Step 1: Adicionar com default (rápido, ~0.1s)
ALTER TABLE users ADD COLUMN age INT DEFAULT 0;
-- Step 2: Aplicação preenche novos registros
const user = { email, name, age };
-- Step 3: Backfill em background
UPDATE users SET age = 18 WHERE age = 0 LIMIT 100000;
-- Step 4: Validar completo
SELECT COUNT(*) FROM users WHERE age = 0;
-- Step 5: Remover DEFAULT
ALTER TABLE users ALTER COLUMN age DROP DEFAULT;

-- Migration v1
ALTER TABLE lesson_progress ADD COLUMN grade VARCHAR(1) DEFAULT 'F';
-- Rápido, coluna com default

-- Aplicação v2 preenche novos registros
// Cada nova resposta calcula grade
const progress = await prisma.lessonProgress.update({
  where: { userId, lessonId },
  data: { grade: calculateGrade(correctCount, totalCount) }
});

-- Background job: backfill antigos (sem lock)
setInterval(async () => {
  const batch = await db.query(
    "SELECT * FROM lesson_progress WHERE grade = 'F' LIMIT 1000"
  );
  for (const p of batch) {
    await db.query(
      "UPDATE lesson_progress SET grade = $1 WHERE id = $2",
      [calculateGrade(p.correctCount, p.totalCount), p.id]
    );
  }
}, 10000); // A cada 10s, backfill 1000 linhas

-- Validação
SELECT COUNT(*) FROM lesson_progress WHERE grade = 'F';
-- Quando zero, backfill completo

-- Migration v3: Adicionar coluna nova
ALTER TABLE users ADD COLUMN email_normalized VARCHAR(255);

-- Migration v4: Popular nova coluna
UPDATE users SET email_normalized = LOWER(email);

-- Rollback (v4 → v3)
DROP COLUMN email_normalized;
-- Dados de email original preservados!

-- Depois: Migration v5
ALTER TABLE users DROP COLUMN email;
-- Só remove quando aplicação v2 não usa mais (semanas depois)
